import java.util.*;

class Solution {
    private int[] nums;
    private int goal, total;
    private Integer[][] memo;

    public int findTargetSumWays(int[] nums, int goal) {
        this.nums = nums;
        this.goal = goal;
        for (int v : nums) total += v;
        if (Math.abs(goal) > total) return 0;           // unreachable
        memo = new Integer[nums.length][2 * total + 1];
        return count(0, 0);
    }

    private int count(int i, int s) {
        if (i == nums.length) return s == goal ? 1 : 0;
        if (memo[i][s + total] != null) return memo[i][s + total]; // shift sum to a valid index
        int ways = count(i + 1, s + nums[i]) + count(i + 1, s - nums[i]);
        memo[i][s + total] = ways;
        return ways;
    }
}

