class Solution:
    def findTargetSumWays(self, nums: List[int], goal: int) -> int:
        @lru_cache(None)
        def go(i, s):
            if i == len(nums): return 1 if s == goal else 0
            return go(i + 1, s + nums[i]) + go(i + 1, s - nums[i])
        return go(0, 0)

