function findTargetSumWays(nums, goal) {
  let m = new Map([[0, 1]]);
  for (const x of nums) { const n = new Map(); for (const [s, c] of m) { n.set(s + x, (n.get(s + x) || 0) + c); n.set(s - x, (n.get(s - x) || 0) + c); } m = n; }
  return m.get(goal) || 0;
}
